export function observationShots(item, layout) {
  if (!item || !layout || !(AUTHORED[item.id]||EXPANDED[item.id])) return [];
  const s=layout.scale, modelY=OBSERVATION_MODEL_Y-(item.modelGroundSourceY||0)*s, world=([x,y,z])=>[(x-layout.center[0])*s,y*s+modelY,(z-layout.center[2])*s];
  return (AUTHORED[item.id]||EXPANDED[item.id]).map((shot,index)=>{
    const floorY=shot.kind==='interior'?shot.floor*s+modelY:OBSERVATION_GROUND_Y;
    const eyeHeight=OBSERVATION_EYE_METRES*s, y=floorY+eyeHeight;
    return {...shot,index,aspect:OBSERVATION_ASPECT,
      position:[(shot.xz[0]-layout.center[0])*s,y,(shot.xz[1]-layout.center[2])*s],
      target:[(shot.look[0]-layout.center[0])*s,y,(shot.look[1]-layout.center[2])*s],
      floorY,eyeHeight,near:.04*s,far:180,
      lensMm:24/(2*Math.tan(shot.fov*Math.PI/360)),
      sourceUnits:'metres',playerRemainsOutside:false, projection:'live-perspective',scale:s,walkRect:{...layout.rect},walkRadius:Math.max(3.2,Math.min(5,4*s)),travelCeiling:item.bounds.max[1]*s+modelY+3,navigation:shot.kind==='interior'?observationNavigation(shot,item,layout):null,
      stationNote:shot.kind==='interior'?'室內地板可行走區':'室外地面可行走區',
      features:shot.features.map(f=>({...f,sourcePoint:[...f.point],point:world(f.point)})),
    };
  });
}
